"""Independent, hand-authored expectations; never generated by the evaluator."""
import hashlib
import json
from pathlib import Path
import subprocess
import sys
from tempfile import TemporaryDirectory
import unittest

from huntlab import run_hunt

ROOT = Path(__file__).resolve().parents[1]


class ExpectedResultTests(unittest.TestCase):
    def expected(self, hunt):
        return json.loads((ROOT / "tests" / "expected" / f"{hunt}-v1.json").read_text(
            encoding="utf-8"))

    def test_complete_results_match_independent_expectations(self):
        for hunt in ("auth", "powershell"):
            with self.subTest(hunt=hunt):
                source = ROOT / "samples" / "logs" / f"{hunt}-lab-v1.csv"
                self.assertEqual(run_hunt(hunt, source), self.expected(hunt))

    def test_cli_repeated_processes_match_independent_expectations(self):
        for hunt in ("auth", "powershell"):
            with self.subTest(hunt=hunt):
                command = [sys.executable, "-B", str(ROOT / "scripts" / "run_hunt.py"),
                           "--hunt", hunt, "--input",
                           str(ROOT / "samples" / "logs" / f"{hunt}-lab-v1.csv")]
                outputs = [subprocess.run(command, capture_output=True, check=True).stdout
                           for _ in range(2)]
                self.assertEqual(outputs[0], outputs[1])
                self.assertEqual(json.loads(outputs[0]), self.expected(hunt))

    def test_hash_matches_independent_digest_and_normalization(self):
        source = ROOT / "samples" / "logs" / "auth-lab-v1.csv"
        normalized = source.read_bytes().decode("utf-8-sig").replace("\r\n", "\n")
        digest = hashlib.sha256(normalized.encode("utf-8")).hexdigest()
        self.assertEqual(digest, self.expected("auth")["input_sha256_normalized_utf8"])
        with TemporaryDirectory() as temp:
            path = Path(temp) / "normalized.csv"
            path.write_bytes(b"\xef\xbb\xbf" + normalized.replace("\n", "\r\n").encode("utf-8"))
            self.assertEqual(run_hunt("auth", path), self.expected("auth"))
            path.write_text(normalized.replace("benign@", "changed@"), encoding="utf-8")
            self.assertNotEqual(run_hunt("auth", path)["input_sha256_normalized_utf8"], digest)


if __name__ == "__main__":
    unittest.main()
